use crate::state::{Canonical, Frame, World};
use std::collections::HashSet;
use std::hash::Hash;
use std::sync::Arc;

#[derive(Default)]
pub(crate) struct Store {
    world: HashSet<Arc<World>>,
    frame: HashSet<Arc<Frame>>,
}

fn share<Value: Eq + Hash>(value: &mut Arc<Value>, table: &mut HashSet<Arc<Value>>) {
    if let Some(previous) = table.get(value) {
        *value = previous.clone();
        return;
    }
    table.insert(value.clone());
}

impl Store {
    pub fn insert(&mut self, mut canonical: Canonical) -> Canonical {
        for index in 0..canonical.state.world.len() {
            share(&mut canonical.state.world[index], &mut self.world);
        }
        for index in 0..canonical.state.frame.len() {
            share(&mut canonical.state.frame[index], &mut self.frame);
        }
        canonical
    }
}

experiment.hash.rs:
use crate::state::{Canonical, Frame};
use std::collections::HashSet;
use std::sync::Arc;

#[derive(Default)]
pub(crate) struct Store {
    frame: HashSet<Arc<Frame>>,
}

impl Store {
    pub fn insert(&mut self, mut canonical: Canonical) -> Canonical {
        for index in 0..canonical.state.frame.len() {
            let value = &mut canonical.state.frame[index];
            if let Some(previous) = self.frame.get(value) {
                *value = previous.clone();
                continue;
            }
            self.frame.insert(value.clone());
        }
        canonical
    }
}

